"""Build volunteer access-badge manifests."""


class BadgeManifestError(ValueError):
    pass


_POLICY_KEYS = {"common_area", "late_shift_area", "role_area"}
_ATTENDEE_KEYS = {"id", "name", "role", "active", "late_shift"}


def _validate_policy(policy):
    if type(policy) is not dict:
        raise BadgeManifestError("policy must be a dictionary")
    if set(policy) != _POLICY_KEYS:
        raise BadgeManifestError("policy has incorrect keys")

    if type(policy["common_area"]) is not str or not policy["common_area"]:
        raise BadgeManifestError("common_area must be a nonempty string")
    if (
        type(policy["late_shift_area"]) is not str
        or not policy["late_shift_area"]
    ):
        raise BadgeManifestError("late_shift_area must be a nonempty string")

    role_area = policy["role_area"]
    if type(role_area) is not dict or not role_area:
        raise BadgeManifestError("role_area must be a nonempty dictionary")

    for role, area in role_area.items():
        if type(role) is not str or not role:
            raise BadgeManifestError("role names must be nonempty strings")
        if type(area) is not str or not area:
            raise BadgeManifestError("role areas must be nonempty strings")


def _validate_attendees(attendees, role_area):
    if type(attendees) is not list:
        raise BadgeManifestError("attendees must be a list")

    seen_ids = set()
    for attendee in attendees:
        if type(attendee) is not dict:
            raise BadgeManifestError("attendees must be dictionaries")
        if set(attendee) != _ATTENDEE_KEYS:
            raise BadgeManifestError("attendee has incorrect keys")

        for field in ("id", "name", "role"):
            if type(attendee[field]) is not str or not attendee[field]:
                raise BadgeManifestError(
                    f"{field} must be a nonempty string"
                )

        if type(attendee["active"]) is not bool:
            raise BadgeManifestError("active must be a boolean")
        if type(attendee["late_shift"]) is not bool:
            raise BadgeManifestError("late_shift must be a boolean")

        attendee_id = attendee["id"]
        if attendee_id in seen_ids:
            raise BadgeManifestError("attendee IDs must be unique")
        seen_ids.add(attendee_id)

        if attendee["role"] not in role_area:
            raise BadgeManifestError("attendee role is not in policy")


def build_manifest(
    attendees: list[object],
    policy: dict[str, object],
) -> list[dict[str, object]]:
    _validate_policy(policy)
    _validate_attendees(attendees, policy["role_area"])

    manifest = []
    for attendee in attendees:
        if not attendee["active"]:
            continue

        areas = [
            policy["common_area"],
            policy["role_area"][attendee["role"]],
        ]
        if attendee["late_shift"]:
            areas.append(policy["late_shift_area"])

        manifest.append(
            {
                "badge_id": attendee["id"],
                "display": (
                    attendee["name"] + " [" + attendee["role"] + "]"
                ),
                "areas": areas,
                "late_shift": attendee["late_shift"],
            }
        )

    manifest.sort(key=lambda entry: entry["badge_id"])
    return manifest
